import { create } from 'zustand'

interface AppLauncherStore {
	appLauncherURL: string | null
	isReady: boolean
	setAppLauncherURL: (appLauncherURL: string | null) => void
}

export const useAppLauncherStore = create<AppLauncherStore>((set) => ({
	appLauncherURL: null,
	isReady: false,
	setAppLauncherURL: (appLauncherURL: string | null) => {
		set({ appLauncherURL, isReady: true })
	}
}))
